/**
 * BACKLOG-4263 (sync 2.49) — the apply files for migrations 20261123100000 (S1) and 20261123110000 (E1).
 *
 * Each apply file is: generated header comment lines, then the migration file's text byte for byte, then exactly the
 * ledger INSERT for that migration's version and name. Generated by supabase/tests/backlog-4263-sync2-s1/gen.py and
 * supabase/tests/backlog-4263-sync2-erase/harness.py write. CI has no database: this checks file text only.
 */

import { createHash } from 'crypto';
import { readFileSync } from 'fs';
import { join } from 'path';

const REPO = join(__dirname, '../../..');
const read = (p: string): string => readFileSync(join(REPO, p), 'utf8').replace(/\r\n?/g, '\n');
const md5 = (s: string): string => createHash('md5').update(s, 'utf8').digest('hex');

const CASES = [
  {
    migration: 'supabase/migrations/20261123100000_backlog_4263_one_computer.sql',
    apply: 'supabase/tests/backlog-4263-sync2-s1/apply-20261123100000.sql',
    version: '20261123100000',
    name: 'backlog_4263_one_computer',
  },
  {
    migration: 'supabase/migrations/20261123110000_backlog_4263_cloud_blob_erase.sql',
    apply: 'supabase/tests/backlog-4263-sync2-erase/apply-20261123110000.sql',
    version: '20261123110000',
    name: 'backlog_4263_cloud_blob_erase',
  },
  {
    migration: 'supabase/migrations/20261123140000_backlog_4263_mcp_message_tools.sql',
    apply: 'supabase/tests/backlog-4263-sync2-t/apply-20261123140000.sql',
    version: '20261123140000',
    name: 'backlog_4263_mcp_message_tools',
  },
];

describe.each(CASES)('apply file $apply', ({ migration, apply, version, name }) => {
  const MIG = read(migration);
  const APPLY = read(apply);

  it('names the migration whose version and name it writes', () => {
    expect(migration.endsWith(`/${version}_${name}.sql`)).toBe(true);
  });

  it('holds the migration text byte for byte, exactly once', () => {
    expect(APPLY.split(MIG)).toHaveLength(2);
  });

  it('has only comment lines before the migration text, naming the migration and its md5', () => {
    const head = APPLY.slice(0, APPLY.indexOf(MIG));
    const lines = head.replace(/\n\n$/, '').split('\n');
    expect(head.endsWith('\n\n')).toBe(true);
    for (const l of lines) expect(l.startsWith('-- ')).toBe(true);
    expect(lines[0]).toMatch(new RegExp(`^-- apply-${version}\\.sql \\(generated by `));
    expect(head).toContain(`-- Migration: ${migration}  file md5 ${md5(MIG)}\n`);
  });

  it('ends with exactly the ledger row for this version and name after the migration text', () => {
    const tail = APPLY.slice(APPLY.indexOf(MIG) + MIG.length);
    expect(tail).toBe(
      '\nINSERT INTO supabase_migrations.schema_migrations (version, name, statements)\n' +
        `VALUES ('${version}', '${name}', ARRAY[]::text[]);\n`,
    );
  });
});
